# -*- coding: utf-8 -*-
p = 'tutorial.py'
L = open(p, encoding='utf-8').read().split('\n')
i1 = next(i for i, l in enumerate(L) if 'урок 1' in l)
i5 = next(i for i, l in enumerate(L) if 'урок 5' in l)
new = r'''    # ------------------------------------------------------------- урок 1
    A('<h2>Урок 1. Палуба (штиль, клетка B4): проходной эпизод</h2>')
    A(teach('<b>Палуба</b> — страница, где игроки выбирают действия. <b>Слоты 1–3</b> (круги) личные: один кубик. <b>Слоты 4–6</b> (пунктир) общие: любое число кубиков. <b>Слот 7</b> — рыбалка, доступна только в штиль. Номер слота — порядок выполнения. Эпизод бывает <b>проходным</b> (один раунд, потом корабль уходит сам) или <b>циклом</b> (круг повторяется, пока корабль не уйдёт). Этот эпизод проходной.'))
    A('<ol><li><b>Эпизод.</b> Писарь читает вслух блок «Читать вслух» ниже (название, описание, предупреждение).</li>'
      '<li><b>Слоты.</b> Объявите: <b>заблокирован слот 1</b> (у проходного эпизода его нет: корабль уйдёт сам); <b>тревожный слот 4 (⚠)</b> «Договориться с джинном». Отметьте ✗ и ⚠ на номерах слотов карандашом.</li>'
      '<li><b>Планирование.</b> По очереди каждый ставит свой кубик на один слот. <b>Это как поставить фигурку-маркер: кубик здесь не бросают.</b> Обсуждать можно. Результаты не читайте. В списке рядом с названием написано, <i>какого навыка проверка</i> (или «без проверки») и каких параметров касается действие, но не сказано, прибавляется оно или убавляется.</li>'
      '<li><b>Действия.</b> По номерам 2 → 7. Если действие — <b>проверка</b>, игрок бросает свой кубик, прибавляет уровень навыка (лист призрака) и называет сумму; Писарь читает исход («что произошло» и числа). Если проверки нет (например, «Перекур»), исход читается сразу. Изменения шкал записывайте в Корабельный журнал, личные значения (Слава, Удача, Добыча) — в листе призрака.</li>'
      '<li><b>Тревожный слот.</b> Если в конце фазы действий на слоте 4 нет кубиков, будет штраф. <i>Для наглядности один раз не ставьте туда кубик и посмотрите штраф в разделе.</i></li>'
      '<li><b>Конец раунда.</b> «Жажда»: Ром −1. Проверьте края шкал. Уберите кубики и отметки.</li>'
      '<li><b>Корабль уходит.</b> Проходной эпизод закончился: группа выбирает соседнюю клетку (<i>в обучении C3</i>) и проводит линию B4 → C3.</li></ol>')
    A(event_block(BY_ID['S2']))
    A(teach('<b>Проверка:</b> бросок d6 + навык (+ бонусы). Если выпало мало, можно потратить <b>Удачу</b>: <b>1 Удача = 1 переброс</b>. Пока у вас её нет: Удачу даёт слот 6 («Перекур»). Слот 7 «Рыбалка» открыт, потому что сейчас штиль: проверка Хватки решает, сколько раз бросать d6 по таблице улова на Палубе (столбец «Штиль»).'))
    A(check('линия B4 → C3 проведена, корабль в C3; Ром 4 (минус Жажда); шкалы записаны.'))

    # ------------------------------------------------------------- урок 2
    A('<h2>Урок 2. Карта (линия, разведка, значок)</h2>')
    A(teach('Откройте <b>Карту</b>. Клетка-<b>сосед</b> — та, что касается стороны вашей. У каждой клетки 6 соседей. <b>Ход</b> — проведите линию в соседнюю клетку. <b>Разведка</b> — для каждой разведываемой клетки бросьте d6 по таблице значков (подсказка справа от карты) и нарисуйте результат. <b>Эпизод определяется значком клетки при каждом заходе</b> (и при повторном тоже): это пул эпизодов типа местности.'))
    A('<ol><li>Покажите линию B4 → C3. Корабль теперь в C3.</li>'
      '<li>Если в уроке 1 кто-то сделал <b>Разведку</b> (слот 2), разведайте указанное число клеток, соседних с кораблём (не C3 и не D3: их значки уже нарисованы). Бросьте d6 для каждой клетки и нарисуйте значок. <i>Это настоящая разведка; значки на пути корабля в обучении фиксированы.</i></li>'
      '<li>Значок C3 — ☁ (туман). Он говорит, что здесь будет эпизод «Туман» (в обучении: F1).</li></ol>')

    # ------------------------------------------------------------- урок 3
    A('<h2>Урок 3. Палуба (туман, клетка C3): цикл</h2>')
    A(teach('<b>Цикл:</b> если корабль не покинул клетку, <b>следующий раунд читается тот же эпизод</b>. Выйти можно слотом 1 «Штурвал» (исход с Ходом). Если никто не выбрал слот 1, обычно штраф. Условие-предмет: некоторые действия открываются, если у кого-то есть нужное снаряжение.'))
    A('<ol><li><b>Подготовка.</b> <i>В обучении</i> любой призрак получает <b>Нюх-флакон</b> (впишите в «Предметы и заметки»).</li>'
      '<li><b>Раунд 3а (демонстрация цикла).</b> Писарь читает блок вслух. Заблокирован слот 7 (рыбалка: не штиль). Слот 6 открыт (есть Нюх-флакон). Планирование и действия как обычно, <b>но не выбирайте слот 1</b>. Последствие: «В конце раунда» — Ром −1, Жажда, и корабль остался в C3.</li>'
      '<li><b>Раунд 3б.</b> Следующий раунд читайте <b>тот же эпизод</b> (название и предупреждение; описание повторять не нужно). Теперь кто-то выбирает слот 1. <i>В обучении слот 1 сдвигает корабль даже при провале: проведите линию C3 → D3.</i></li>'
      '<li>Если у кого-то есть Удача, покажите, как её тратить: <b>1 Удача = 1 переброс</b>.</li>'
      '<li><i>В обучении Ход здесь не больше одной клетки.</i></li></ol>')
    A(event_block(BY_ID['F1']))
    A(check('линия C3 → D3, Ром ниже, чем в конце урока 1 (минимум на 2).'))

    # ------------------------------------------------------------- урок 4
    A('<h2>Урок 4. Палуба и Судовой журнал (шторм, клетка D3): цикл и обязательный слот</h2>')
    A(teach('Шторм — цикл. <b>Обязательный слот («!»)</b>: кто-то из игроков <b>обязан</b> поставить туда кубик; ситуации «никто не поставил» нет. Слот 1 «Штурвал» не обязателен: но если никто его не выберет, штраф и новый круг.'))
    A('<ol><li>В D3 читайте эпизод шторма вслух, включая предупреждение.</li>'
      '<li>Слот 4 «Крепить такелаж» <b>обязателен</b> («!»): кто-то из игроков обязан поставить туда кубик. Остальные выбирают как обычно. <i>В обучении кто-то берёт слот 1: сразу уходим из шторма.</i></li>'
      '<li>Действия по номерам. <i>В обучении слот 1 сдвигает корабль: линия D3 → E3 (порт).</i></li>'
      '<li><b>В конце раунда:</b> «В конце раунда» эпизода, Жажда (Ром −1), края шкал.</li>'
      '<li><b>Судовой журнал.</b> Откройте последнюю страницу буклета (стр. 8). Таблица: сверху цифры 1–6, слева значки. <i>В обучении</i> после шторма закрасьте <b>первую клетку в строке «штурвал»</b>: это ключевое слово. Позже (урок 5) мы проверим журнал.</li></ol>')
    A(event_block(BY_ID['ST1']))
    A(check('линия D3 → E3, корабль в порту; ключевое слово записано, Корпус мог упасть, шкалы актуальны.'))
'''.split('\n')
L = L[:i1] + new + L[i5:]
open(p, 'w', encoding='utf-8').write('\n'.join(L))
print('ok')
